mapper.select:
select count(1)
from `ry_rental`.`ry_rental_model`
where class_id = #{classId}
  and brand_id = #{brandId}
  and model_name = #{modelName}
  and coalesce(memory_spec, '') = coalesce(#{memorySpec}, '')
  and is_delete = 0
and model_id != #{excludeModelId}

mapper.insert:
insert into `ry_rental`.`ry_rental_model`(
    class_id, brand_id, model_name, `alias`, memory_spec, official_flag, status,
    is_delete, create_by, create_time, remark
) values (
    #{classId}, #{brandId}, #{modelName}, #{alias}, #{memorySpec}, #{officialFlag}, #{status},
    0, #{createBy}, sysdate(), #{remark}
)
